const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(new Cesium.OpenStreetMapImageryProvider({
    url: 'https://tile.openstreetmap.org/',
    maximumLevel: 18
  })),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false
}));

viewer.scene.globe.enableLighting = false;

// 5 SW US cities: [lon, lat, ...]
const cityCoords = [
  { name: 'Los Angeles',   lon: -118.2437, lat: 34.0522 },
  { name: 'Phoenix',       lon: -112.0740, lat: 33.4484 },
  { name: 'Las Vegas',     lon: -115.1398, lat: 36.1699 },
  { name: 'Denver',        lon: -104.9903, lat: 39.7392 },
  { name: 'Albuquerque',   lon: -106.6504, lat: 35.0844 },
];

// Build positions array via fromDegreesArray
const degreesFlat = cityCoords.flatMap(c => [c.lon, c.lat]);
const positions = Cesium.Cartesian3.fromDegreesArray(degreesFlat);

// Compute bounding sphere
const bs = Cesium.BoundingSphere.fromPoints(positions);

// Convert bs.center -> Cartographic -> Cartesian3.fromRadians (round-trip as required)
const centerCarto = Cesium.Cartographic.fromCartesian(bs.center);
const centerPosition = Cesium.Cartesian3.fromRadians(
  centerCarto.longitude,
  centerCarto.latitude,
  centerCarto.height
);

// Add ellipsoid entity at bounding sphere center
viewer.entities.add({
  name: 'BoundingSphere',
  position: centerPosition,
  ellipsoid: {
    radii: new Cesium.Cartesian3(bs.radius, bs.radius, bs.radius),
    material: Cesium.Color.YELLOW.withAlpha(0.3),
    outline: true,
    outlineColor: Cesium.Color.YELLOW,
    outlineWidth: 2,
  }
});

// Add 5 cyan point entities at city positions
cityCoords.forEach((city, i) => {
  viewer.entities.add({
    name: city.name,
    position: positions[i],
    point: {
      pixelSize: 18,
      color: Cesium.Color.CYAN,
      outlineColor: Cesium.Color.WHITE,
      outlineWidth: 2,
    },
    label: {
      text: city.name,
      font: '13px sans-serif',
      fillColor: Cesium.Color.WHITE,
      outlineColor: Cesium.Color.BLACK,
      outlineWidth: 2,
      style: Cesium.LabelStyle.FILL_AND_OUTLINE,
      verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
      pixelOffset: new Cesium.Cartesian2(0, -12),
    }
  });
});

// Frame camera to show entire bounding sphere region
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-110, 36, 8000000),
  orientation: {
    heading: 0.0,
    pitch: Cesium.Math.toRadians(-90),
    roll: 0.0
  }
});
